import numpy as np
from scipy.optimize import least_squares
S=df.S.values; I=df.I.values; v=df.v.values
def mixed(p,S,I):
    Vm,Km,Ki,a=p
    return Vm*S/(Km*(1+I/Ki)+S*(1+I/(a*Ki)))
best=None
for Vm in [8,10]:
  for Km in [1,3]:
    for Ki in [1,5]:
      for a in [0.1,0.5,2]:
        r=least_squares(lambda p:mixed(p,S,I)-v,[Vm,Km,Ki,a],bounds=([0,0,0,0],[100,100,100,100]))
        if best is None or r.cost<best.cost: best=r
rss=2*best.cost; n=len(v);k=4
print(best.x, rss, 'sigma',np.sqrt(rss/(n-k)),'BIC',n*np.log(rss/n)+k*np.log(n))
res=v-mixed(best.x,S,I)
for i in sorted(set(I)): print(i, res[I==i].mean().round(3), (res[I==i]/np.sqrt(rss/n)).round(1))

